import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Regression tests for binding scope at OPTIONAL boundaries. Each assertion compares the complete RDF mapping bag,
 * including the exact set of bound names and duplicate rows.
 */
public class MemoryOptionalBindingScopeRegressionTest {

	private static final SimpleValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	@Test
	public void issue4882_optionalBindDoesNotInheritOuterValues() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { BIND(?x AS ?y) } }",
				List.of(row("x", literal("left"))));
	}

	@Test
	public void issue4882_coalesceReadsRightOperandScope() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
				+ "BIND(COALESCE(?x, \"fallback\") AS ?y) } }",
				List.of(row("x", literal("left"), "y", literal("fallback"))));
	}

	@Test
	public void issue4882_boundReadsRightOperandScope() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { BIND(BOUND(?x) AS ?y) } }",
				List.of(row("x", literal("left"), "y", VALUE_FACTORY.createLiteral(false))));
	}

	@Test
	public void issue4882_ifReadsRightOperandScope() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
				+ "BIND(IF(BOUND(?x), 1/0, \"fallback\") AS ?y) } }",
				List.of(row("x", literal("left"), "y", literal("fallback"))));
	}

	@Test
	public void issue4882_liftedOptionalFilterSeesOuterValueButBindDoesNot() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
				+ "FILTER(BOUND(?x)) BIND(\"yes\" AS ?y) BIND(?x AS ?z) } }",
				List.of(row("x", literal("left"), "y", literal("yes"))));
	}

	@Test
	public void sameGroupFilterAndBindSeeTheirGroupInput() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } FILTER(BOUND(?x)) BIND(?x AS ?y) }",
				List.of(row("x", literal("left"), "y", literal("left"))));
	}

	@Test
	public void liftedOptionalConditionSeesEachCompatibleMergedRow() {
		assertSolutions("SELECT * WHERE { VALUES (?x ?limit) { "
				+ "(\"1\" \"1\") (\"1\" \"2\") (UNDEF \"1\") (\"2\" \"2\") (\"2\" \"2\") } "
				+ "OPTIONAL { VALUES (?x ?y) { (\"1\" \"1\") (\"2\" \"2\") } FILTER(?y = ?limit) } }",
				List.of(row("x", literal("1"), "limit", literal("1"), "y", literal("1")),
						row("x", literal("1"), "limit", literal("2")),
						row("x", literal("1"), "limit", literal("1"), "y", literal("1")),
						row("x", literal("2"), "limit", literal("2"), "y", literal("2")),
						row("x", literal("2"), "limit", literal("2"), "y", literal("2"))));
	}

	@Test
	public void liftedOptionalConditionSeesLeftValueWhenRightValueIsUnbound() {
		assertSolutions("SELECT * WHERE { VALUES (?x ?limit) { (\"1\" \"1\") } OPTIONAL { "
				+ "VALUES (?x ?y) { (UNDEF \"one\") (\"2\" \"two\") } FILTER(?x = ?limit) } }",
				List.of(row("x", literal("1"), "limit", literal("1"), "y", literal("one"))));
	}

	@Test
	public void issue6402_minusDoesNotInheritOuterValue() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
				+ "VALUES ?o { \"left\" } MINUS { BIND(?x AS ?o) } } }",
				List.of(row("x", literal("left"), "o", literal("left"))));
	}

	@Test
	public void issue6389_optionalBindTargetConflictKeepsLeftValue() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { BIND(\"right\" AS ?x) } }",
				List.of(row("x", literal("left"))));
	}

	@Test
	public void issue6389_failedOptionalBindKeepsLeftAndRightValues() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
				+ "VALUES ?o { \"abc\" } BIND(?o + 1 AS ?x) } }",
				List.of(row("x", literal("left"), "o", literal("abc"))));
	}

	@Test
	public void issue6403_optionalUnionFilterArmKeepsOnlyOtherBranch() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
				+ "{ FILTER(BOUND(?x)) BIND(\"yes\" AS ?y) } UNION { BIND(\"other\" AS ?y) } } }",
				List.of(row("x", literal("left"), "y", literal("other"))));
	}

	@Test
	public void issue6404_nestedOptionalConditionDoesNotBindInnerValues() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
				+ "VALUES ?o { \"o\" } OPTIONAL { VALUES ?z { \"z\" } FILTER(BOUND(?x)) } } }",
				List.of(row("x", literal("left"), "o", literal("o"))));
	}

	@Test
	public void duplicateOuterValuesRemainDuplicateSolutions() {
		assertSolutions("SELECT * WHERE { VALUES ?x { \"left\" \"left\" } OPTIONAL { BIND(?x AS ?y) } }",
				List.of(row("x", literal("left")), row("x", literal("left"))));
	}

	private void assertSolutions(String query, List<Map<String, Value>> expected) {
		List<Map<String, Value>> actual = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult results = connection.prepareTupleQuery(query).evaluate()) {
			while (results.hasNext()) {
				actual.add(asRow(results.next()));
			}
		}
		assertThat(actual)
				.as("complete RDF solution bag for %s", query)
				.containsExactlyInAnyOrderElementsOf(expected);
	}

	private static Map<String, Value> asRow(BindingSet bindings) {
		Map<String, Value> row = new TreeMap<>();
		for (String name : bindings.getBindingNames()) {
			row.put(name, bindings.getValue(name));
		}
		return row;
	}

	private static Map<String, Value> row(Object... nameValuePairs) {
		if (nameValuePairs.length == 0 || nameValuePairs.length % 2 != 0) {
			throw new IllegalArgumentException("A solution row requires one or more name/value pairs");
		}
		Map<String, Value> row = new TreeMap<>();
		for (int i = 0; i < nameValuePairs.length; i += 2) {
			String name = (String) nameValuePairs[i];
			Value value = (Value) nameValuePairs[i + 1];
			if (row.put(name, value) != null) {
				throw new IllegalArgumentException("Duplicate binding name: " + name);
			}
		}
		return row;
	}

	private static Value literal(String value) {
		return VALUE_FACTORY.createLiteral(value);
	}
}
